package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.BeanProperty;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.UnresolvedForwardReference;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId.Referring;
import com.fasterxml.jackson.databind.deser.impl.StdValueInstantiator;
import com.fasterxml.jackson.databind.deser.std.ContainerDeserializerBase;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Collection;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class CollectionDeserializer_createContextual_TriageGen1Test {

    private DeserializationContext ctxt;
    private BeanProperty property;
    private JavaType collectionType;
    private JavaType contentType;
    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
        typeFactory = TypeFactory.defaultInstance();
        collectionType = typeFactory.constructCollectionType(Collection.class, String.class);
        contentType = collectionType.getContentType();

        // Default behavior for ctxt to avoid NPEs in common paths
        when(ctxt.getConfig()).thenReturn(ctxt.getCodec().getDeserializationConfig());
    }

    @Test
    public void testCreateContextual_NoInstantiator_NoValueDeser() throws JsonMappingException {
        CollectionDeserializer deser = new CollectionDeserializer(collectionType, null, null, null);

        when(ctxt.findContextualValueDeserializer(contentType, property)).thenReturn(mock(StdDeserializer.class));

        CollectionDeserializer result = deser.createContextual(ctxt, property);

        assertNotNull(result);
        verify(ctxt).findContextualValueDeserializer(contentType, property);
    }

    @Test
    public void testCreateContextual_WithInstantiator_DelegateTypeNullThrowsException() {
        StdValueInstantiator instantiator = new StdValueInstantiator(CollectionDeserializer.class) {
            @Override
            public boolean canCreateUsingDelegate() { return true; }
            @Override
            public JavaType getDelegateType(com.fasterxml.jackson.databind.DeserializationConfig config) { return null; }
        };

        CollectionDeserializer deser = new CollectionDeserializer(collectionType, null, null, instantiator);

        try {
            deser.createContextual(ctxt, property);
            fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Invalid delegate-creator definition"));
        } catch (Exception e) {
            fail("Wrong exception type: " + e.getClass().getName());
        }
    }

    @Test
    public void testCreateContextual_WithInstantiator_SuccessfulDelegate() throws JsonMappingException {
        JavaType delegateType = typeFactory.constructType(String.class);
        StdValueInstantiator instantiator = new StdValueInstantiator(CollectionDeserializer.class) {
            @Override
            public boolean canCreateUsingDelegate() { return true; }
            @Override
            public JavaType getDelegateType(com.fasterxml.jackson.databind.DeserializationConfig config) { return delegateType; }
        };

        // Spy to mock findDeserializer which is protected and called internally
        CollectionDeserializer deser = spy(new CollectionDeserializer(collectionType, null, null, instantiator));
        JsonDeserializer<Object> delegateDeser = mock(JsonDeserializer.class);

        doReturn(delegateDeser).when(deser).findDeserializer(any(), eq(delegateType), any());
        when(ctxt.findContextualValueDeserializer(contentType, property)).thenReturn(mock(StdDeserializer.class));

        CollectionDeserializer result = deser.createContextual(ctxt, property);

        assertNotNull(result);
        verify(deser).findDeserializer(eq(ctxt), eq(delegateType), eq(property));
    }

    @Test
    public void testCreateContextual_WithExistingValueDeser_TriggersHandleSecondaryContextualization() throws JsonMappingException {
        JsonDeserializer<Object> existingValueDeser = mock(JsonDeserializer.class);
        JsonDeserializer<Object> contextualizedValueDeser = mock(JsonDeserializer.class);

        CollectionDeserializer deser = new CollectionDeserializer(collectionType, existingValueDeser, null, null);

        when(ctxt.handleSecondaryContextualization(eq(existingValueDeser), eq(property), eq(contentType)))
                .thenReturn(contextualizedValueDeser);

        CollectionDeserializer result = deser.createContextual(ctxt, property);

        assertNotNull(result);
        verify(ctxt).handleSecondaryContextualization(existingValueDeser, property, contentType);
    }

    @Test
    public void testCreateContextual_WithValueTypeDeserializer() throws JsonMappingException {
        JsonDeserializer<Object> valueDeser = mock(JsonDeserializer.class);
        com.fasterxml.jackson.databind.deser.impl.TypeDeserializer typeDeser = mock(com.fasterxml.jackson.databind.deser.impl.TypeDeserializer.class);
        com.fasterxml.jackson.databind.deser.impl.TypeDeserializer contextualTypeDeser = mock(com.fasterxml.jackson.databind.deser.impl.TypeDeserializer.class);

        CollectionDeserializer deser = new CollectionDeserializer(collectionType, valueDeser, typeDeser, null);

        when(ctxt.handleSecondaryContextualization(any(), any(), any())).thenReturn(valueDeser);
        when(typeDeser.forProperty(property)).thenReturn(contextualTypeDeser);

        CollectionDeserializer result = deser.createContextual(ctxt, property);

        assertNotNull(result);
        verify(typeDeser).forProperty(property);
    }

    @Test
    public void testCreateContextual_FindConvertingContentDeserializerPath() throws JsonMappingException {
        JsonDeserializer<Object> valueDeser = mock(JsonDeserializer.class);
        CollectionDeserializer deser = spy(new CollectionDeserializer(collectionType, valueDeser, null, null));

        // Mock findConvertingContentDeserializer to return same deserializer (simulating no conversion)
        doReturn(valueDeser).when(deser).findConvertingContentDeserializer(any(), any(), any());
        when(ctxt.handleSecondaryContextualization(any(), any(), any())).thenReturn(valueDeser);

        CollectionDeserializer result = deser.createContextual(ctxt, property);

        assertNotNull(result);
        verify(deser).findConvertingContentDeserializer(eq(ctxt), eq(property), eq(valueDeser));
    }
}
